INSERT INTO anime_works (id, title, title_en, genre, year, image_url, description) VALUES ('a05140000-0000-4000-8000-000000000000', 'AKIRA', 'Akira', '映画', 1988, '', '大友克洋による近未来SFアニメ映画の金字塔。2019年のネオ東京を舞台にした壮大な物語。');
