INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05230001-0000-4000-8000-000000000000', 'a05230000-0000-4000-8000-000000000000', '屋久島（もののけ姫の森）', '鹿児島県熊毛郡屋久島町', 30.3397, 130.5048, '苔むした原生林が腐海の底を思わせる。宮崎作品の自然観の原点。', '全編', '屋久島空港または宮之浦港から', '{"屋久島","原生林","苔"}');
