INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05430002-0000-4000-8000-000000000000', 'a05430000-0000-4000-8000-000000000000', '上橋菜穂子の地元（東京都）', '東京都調布市小島町1丁目', 35.6516, 139.5425, '上橋菜穂子が教鞭をとった調布市。精霊の守り人の原点を感じる。', '作品全体', '京王線 調布駅すぐ', '{"調布","出身地","東京"}');
INSERT INTO anime_works (id, title, title_en, genre, year, image_url, description) VALUES ('a05440000-0000-4000-8000-000000000000', 'ガングレイヴ', 'Gungrave', 'TVアニメ', 2003, '', '内藤泰弘原案のマフィアアクションアニメ。親友同士の絆と裏切りを描くハードボイルドな物語。');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05440000-0000-4000-8000-000000000000', 'a05440000-0000-4000-8000-000000000000', '横浜赤レンガ倉庫', '神奈川県横浜市中区新港1-1', 35.4531, 139.6428, 'マフィアの暗躍する港町のイメージ。異国情緒あふれるレンガ建築。', '全編', 'みなとみらい線 馬車道駅から徒歩6分', '{"赤レンガ","横浜","港"}');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05440001-0000-4000-8000-000000000000', 'a05440000-0000-4000-8000-000000000000', '横浜中華街', '神奈川県横浜市中区山下町', 35.4436, 139.6499, 'マフィアの抗争が繰り広げられる裏社会のイメージ。活気ある異国の街。', '中盤', 'みなとみらい線 元町・中華街駅すぐ', '{"中華街","横浜","裏社会"}');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05440002-0000-4000-8000-000000000000', 'a05440000-0000-4000-8000-000000000000', '山下公園', '神奈川県横浜市中区山下町279', 35.4441, 139.6528, 'ブランドンとハリーが語り合った港の公園のイメージ。横浜港を一望。', '序盤', 'みなとみらい線 元町・中華街駅から徒歩3分', '{"山下公園","横浜","港"}');
INSERT INTO anime_works (id, title, title_en, genre, year, image_url, description) VALUES ('a05450000-0000-4000-8000-000000000000', 'クレヨンしんちゃん', 'Crayon Shin-chan', 'TVアニメ', 1992, '', '臼井儀人原作の国民的ギャグアニメ。春日部に住む野原しんのすけと家族のドタバタな日常。');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05450000-0000-4000-8000-000000000000', 'a05450000-0000-4000-8000-000000000000', '春日部駅', '埼玉県春日部市粕壁1丁目', 35.9767, 139.752, 'しんちゃんの街・春日部の玄関口。駅前にはしんちゃんのオブジェも。', '全編', '東武スカイツリーライン 春日部駅すぐ', '{"春日部","駅","しんちゃん"}');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05450001-0000-4000-8000-000000000000', 'a05450000-0000-4000-8000-000000000000', 'ララガーデン春日部', '埼玉県春日部市南1-1-1', 35.974, 139.7488, 'サトーココノカドーのモデルとされるショッピングモール。', '全編', '東武スカイツリーライン 春日部駅から徒歩3分', '{"ショッピング","春日部","サトーココノカドー"}');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05450002-0000-4000-8000-000000000000', 'a05450000-0000-4000-8000-000000000000', '春日部市立図書館（旧館）', '埼玉県春日部市粕壁東2-8-29', 35.9795, 139.7555, 'ふたば幼稚園のモデルとされる地域の建物。しんちゃんの日常の舞台。', '全編', '東武スカイツリーライン 春日部駅から徒歩8分', '{"図書館","春日部","幼稚園"}');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05450003-0000-4000-8000-000000000000', 'a05450000-0000-4000-8000-000000000000', 'クレヨンしんちゃんオフィシャルショップ', '埼玉県春日部市南1-1-1 ララガーデン春日部2F', 35.974, 139.7488, '公式グッズショップ。しんちゃんファンの聖地巡礼の拠点。', '全編', '東武スカイツリーライン 春日部駅から徒歩3分', '{"ショップ","春日部","グッズ"}');
INSERT INTO anime_works (id, title, title_en, genre, year, image_url, description) VALUES ('a05460000-0000-4000-8000-000000000000', 'ドラえもん', 'Doraemon', 'TVアニメ', 1979, '', '藤子・F・不二雄原作の国民的アニメ。22世紀からやってきたネコ型ロボット・ドラえもんとのび太の物語。');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05460000-0000-4000-8000-000000000000', 'a05460000-0000-4000-8000-000000000000', '藤子・F・不二雄ミュージアム', '神奈川県川崎市多摩区長尾2-8-1', 35.6117, 139.5636, 'ドラえもんの原作者の記念館。原画や展示物が充実。ファン必訪の聖地。', '作品全体', '小田急線 向ヶ丘遊園駅からバス9分', '{"ミュージアム","川崎","藤子・F・不二雄"}');
