INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05460002-0000-4000-8000-000000000000', 'a05460000-0000-4000-8000-000000000000', '高岡おとぎの森公園（ドラえもんの空き地）', '富山県高岡市佐野1342', 36.7364, 137.0217, '藤子・F・不二雄の出身地・高岡にあるドラえもんの空き地の再現。土管もある。', '全編', 'JR城端線 二塚駅から徒歩15分', '{"高岡","空き地","土管"}');
INSERT INTO pilgrimage_spots (id, work_id, name, address, lat, lng, scene_description, episode, access_info, tags) VALUES ('b05460003-0000-4000-8000-000000000000', 'a05460000-0000-4000-8000-000000000000', 'ドラえもんトラム（万葉線）', '富山県高岡市下関町6-1', 36.7502, 137.0249, 'ドラえもんのキャラクターがデザインされた路面電車。高岡駅から乗車可能。', '全編', 'JR高岡駅すぐ', '{"路面電車","高岡","ドラえもんトラム"}');
